// WF-ANI · node "Verify + Normalize"
// Auth accepts EITHER credential, evaluated independently, passing if either matches:
//   • x-rate-secret       — the shared secret verbatim (what the Retell custom tool sends)
//   • x-retell-signature  — HMAC-SHA256 of the exact body under RATE_SHARED_SECRET
// Aug 24 2026 FIX: the old ladder tested the signature FIRST and only fell through to the
// shared secret when no signature header existed. Retell attaches x-retell-signature to
// every tool call and signs it with ITS OWN key, so the shared-secret branch became
// unreachable and every lookup 401'd. The 401 body is a well-formed known_caller:false,
// so the flow read it as "not a customer" and greeted warm callers cold — silently.
const crypto = require('crypto');

const item = $input.first().json || {};
const headers = item.headers || {};
const body = item.body || {};

const SECRET = ($vars && $vars.RATE_SHARED_SECRET) || '';

const hdr = (k) => {
  const lk = String(k).toLowerCase();
  const keys = Object.keys(headers);
  for (let i = 0; i < keys.length; i++) {
    if (String(keys[i]).toLowerCase() === lk) return String(headers[keys[i]] == null ? '' : headers[keys[i]]);
  }
  return '';
};

const ctEq = (a, b) => {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  const ba = Buffer.from(a, 'utf8');
  const bb = Buffer.from(b, 'utf8');
  if (ba.length !== bb.length) return false;
  return crypto.timingSafeEqual(ba, bb);
};

let auth_ok = false;
let auth_mode = 'none';
let auth_reason = '';

if (!SECRET) {
  auth_reason = 'RATE_SHARED_SECRET is not set in n8n Variables';
} else {
  const sig = hdr('x-retell-signature');
  const shared = hdr('x-rate-secret');
  const tried = [];

  if (shared) {
    tried.push('shared');
    if (ctEq(shared, SECRET)) { auth_ok = true; auth_mode = 'shared'; }
  }

  if (!auth_ok && sig) {
    tried.push('hmac');
    const expected = crypto.createHmac('sha256', SECRET).update(JSON.stringify(body)).digest('hex');
    const parts = String(sig).split(/[,;\s]+/);
    for (let i = 0; i < parts.length; i++) {
      const p = parts[i];
      if (!p) continue;
      const eq = p.indexOf('=');
      const cand = eq >= 0 ? p.slice(eq + 1).trim() : p.trim();
      if (ctEq(cand.toLowerCase(), expected)) { auth_ok = true; auth_mode = 'hmac'; break; }
    }
  }

  if (!auth_ok) {
    auth_mode = tried.length ? tried.join('+') : 'none';
    auth_reason = tried.length
      ? ('no supplied credential matched (tried: ' + tried.join(', ') + ')')
      : 'neither x-rate-secret nor x-retell-signature was supplied';
  }
}

const args = body.args || body.arguments || body.parameters || body;
const call = body.call || {};

const str = (v) => (v === undefined || v === null) ? '' : String(v).trim();

// E.164 normalization. NANP numbers arrive as digits, +1XXXXXXXXXX, or spoken-with-punctuation.
const rawPhone = str(args.phone_e164 || args.phone || args.from_number || call.from_number);
let digits = rawPhone.replace(/[^0-9]/g, '');
if (digits.length === 10) digits = '1' + digits;
const phone_e164 = digits ? ('+' + digits) : '';
const phone_valid = /^\+[1-9]\d{7,14}$/.test(phone_e164);

return [{
  json: {
    auth_ok: auth_ok,
    auth_mode: auth_mode,
    auth_reason: auth_reason,
    phone_e164: phone_e164,
    phone_valid: phone_valid,
    phone_query: encodeURIComponent(phone_e164),
    tenant_id: str(args.tenant_id || body.tenant_id) || 'demo',
    call_id: str(args.call_id || body.call_id || call.call_id),
    started_ms: Date.now()
  }
}];

// WF-ANI · node "Build ANI Response"
// One GHL round trip only. /contacts/search/duplicate carries customFields (measured
// 2026-08-03: median ~200ms, cf present), so identity + last trip + billing all come
// from a single call. Budget raised Aug 22: 360ms caused coin-flip recognition on
// GHL's slow moments (p95 runs 1–2s) — warm callers were greeted cold. 2500ms rides
// under the opening greeting, so recognition succeeds through normal CRM jitter while
// a truly dead CRM still degrades to a fast miss instead of holding the line.
const n = $('Verify + Normalize').first().json;
const res = $input.first().json || {};

// Hard endpoint budget. The GHL node's own timeout is set at this value so a slow CRM
// degrades to a fast-miss instead of holding the agent on a silent line.
const BUDGET_MS = 2500;

// GHL contact custom-field ids (contact model). Verified against the live location.
const F = {
  trip_type: 'qta1B3kERujMTLNDlj66',
  pickup_datetime: 'HOfBlSbheMOtChBuK0vU',
  pickup_address: 'L9FS4ZqII0OvQe5KESh7',
  dropoff_address: 'ISMLWbZhk0V9eVHXut86',
  vehicle_class: 'OtmDBeaHItbSvOUHRTGY',
  billing_type: 'Z36xyFEoF9brVdNeKAIP',
  tenant: '16MIe7L45qETn9TtcOK5'
};

const elapsed = Date.now() - (n.started_ms || Date.now());

// neverError is on the HTTP node, so a timeout / 401 / 5xx arrives as an ITEM, not a throw.
// A failed lookup must never be reported as a verified "not a customer" — that is the
// false-verification shape this endpoint exists to avoid. Any non-2xx, any error field,
// or a body with neither `contact` nor a trace id counts as a failure, not a miss.
const sc = Number(res.statusCode || res.status || 0);
const httpFailed = !!(
  res.error ||
  res.message === 'error' ||
  res.code ||
  (sc && (sc < 200 || sc >= 300)) ||
  (!Object.prototype.hasOwnProperty.call(res, 'contact') && !res.traceId)
);
const contact = (!httpFailed && res && res.contact) ? res.contact : null;

const cfMap = {};
const cfArr = (contact && Array.isArray(contact.customFields)) ? contact.customFields : [];
for (let i = 0; i < cfArr.length; i++) {
  const f = cfArr[i] || {};
  const id = f.id || f.fieldId || '';
  const v = (f.value !== undefined && f.value !== null) ? f.value : f.field_value;
  if (id) cfMap[id] = (v === undefined || v === null) ? '' : String(v);
}
const cf = (k) => (cfMap[F[k]] || '').trim();

const nn = (v) => {
  const s = (v === undefined || v === null) ? '' : String(v).trim();
  return s === '' ? null : s;
};

let reason = '';
let data_verified = false;
let known = false;

if (!n.auth_ok) {
  reason = 'unauthorized';
} else if (!n.phone_valid) {
  reason = 'NO_ANI — caller id was absent or not a dialable number';
} else if (httpFailed) {
  reason = 'FAST_MISS — CRM lookup failed or did not answer inside the ' + BUDGET_MS +
           'ms budget (http ' + (sc || 'n/a') + ')';
} else if (!contact || !contact.id) {
  reason = 'NO_MATCH — no CRM record for this number';
  data_verified = true; // the lookup completed; "not a customer" is a verified answer
} else {
  known = true;
  data_verified = true;
  reason = 'MATCH';
}

// account_type: corporate when the CRM says so (direct bill / new account) or a company
// is on file. Never guessed from the area code.
const billing = cf('billing_type').toUpperCase();
let account_type = null;
if (known) {
  if (billing === 'DIRECT_BILL' || billing === 'NEW_ACCOUNT') account_type = 'corporate';
  else if (billing === 'CC_ON_FILE') account_type = 'retail';
  else account_type = nn(contact.companyName) ? 'corporate' : 'retail';
}

// last_trip is only reported when the CRM actually holds one. Never invented.
let last_trip = null;
if (known) {
  const when = cf('pickup_datetime');
  const what = cf('trip_type');
  const from = cf('pickup_address');
  const to = cf('dropoff_address');
  const veh = cf('vehicle_class');
  if (when || what || from) {
    last_trip = {
      trip_type: nn(what),
      pickup_datetime: nn(when),
      pickup_address: nn(from),
      dropoff_address: nn(to),
      vehicle_class: nn(veh)
    };
  }
}

// rate_plan mirrors the billing arrangement on the record. Null when unset — a
// missing plan prints "— NOT PROVIDED" rather than defaulting a customer onto retail.
const rate_plan = known ? (nn(billing) ? billing : null) : null;

return [{
  json: {
    known_caller: known,
    first_name: known ? nn(contact.firstName) : null,
    company_name: known ? nn(contact.companyName) : null,
    account_type: account_type,
    last_trip: last_trip,
    rate_plan: rate_plan,
    ghl_contact_id: known ? nn(contact.id) : null,
    data_verified: data_verified,
    reason: reason,
    phone_e164: n.phone_e164 || null,
    tenant_id: n.tenant_id,
    call_id: n.call_id,
    lookup_ms: elapsed
  }
}];

// Pre-call inbound extract. Retell inbound_call_webhook posts { event, call_inbound: { agent_id, from_number, to_number } }.
const b = ($input.first().json || {}).body || {};
const ci = b.call_inbound || {};
const s = (v) => (v == null ? '' : String(v)).trim();
let d = s(ci.from_number || b.from_number).replace(/[^0-9]/g, '');
if (d.length === 10) d = '1' + d;
const e164 = d ? ('+' + d) : '';
return [{ json: {
  from_e164: e164,
  valid: /^\+[1-9]\d{7,14}$/.test(e164),
  agent_id: s(ci.agent_id || b.agent_id),
  to_number: s(ci.to_number || b.to_number),
  t0: Date.now()
} }];

// Pre-call variable builder. RECOGNITION-SILENCE LAW: any failure, timeout, bad ANI,
// or tenant mismatch degrades to cold — recognition never guesses. All values are
// STRINGS because Retell dynamic_variables reject nested objects and nulls.
// TENANT-ISOLATION LAW: identity (name/company) may be shared across the location;
// trip details surface ONLY when the contact's tenant field says AI Chauffeur and
// the call is on the AI Chauffeur agent. Reliable callers never hear another desk's trip.
const x = $('Inbound Extract').first().json;
const res = $input.first().json || {};
const CHAUF = 'agent_2d1d687eb85e6d5d0e720795c2';
const s = (v) => (v == null ? '' : String(v)).trim();
const sc = Number(res.statusCode || res.status || 0);
const failed = !!(res.error || res.code || (sc && (sc < 200 || sc >= 300)) || (!Object.prototype.hasOwnProperty.call(res, 'contact') && !res.traceId));
const c = (!failed && res.contact) ? res.contact : null;
const F = { trip: 'qta1B3kERujMTLNDlj66', when: 'HOfBlSbheMOtChBuK0vU', pu: 'L9FS4ZqII0OvQe5KESh7', doff: 'ISMLWbZhk0V9eVHXut86', veh: 'OtmDBeaHItbSvOUHRTGY', ten: '16MIe7L45qETn9TtcOK5' };
const cfm = {};
for (const f of (c && Array.isArray(c.customFields) ? c.customFields : [])) { const id = f.id || f.fieldId; const v = (f.value !== undefined && f.value !== null) ? f.value : f.field_value; if (id) cfm[id] = s(v); }
const cf = (k) => cfm[F[k]] || '';
const known = !!(x.valid && !failed && c && c.id);
const verified = !!(x.valid && !failed);
const tenOk = cf('ten') === 'AI Chauffeur';
const chaufLine = (x.agent_id === '' || x.agent_id === CHAUF);
const VM = { sedan_exec: 'Executive Sedan', sedan_luxury: 'Luxury Sedan', suv_exec: 'Executive SUV', suv_premium: 'Premium Executive SUV', van_exec: 'Executive Van', van_ada: 'ADA Accessible Van', sprinter_exec_14: 'Executive Sprinter Coach', sprinter_luxury: 'Luxury Sprinter Coach', limo_stretch: 'Stretch Limousine', limo_super_stretch: 'Super Stretch Limousine', limo_hummer: 'Hummer Limousine', party_bus_20: 'Party Bus (20)', party_bus_30: 'Party Bus (30)', party_bus_40: 'Party Bus (40)', mini_coach_32: 'Mini Coach (32)', mini_coach_38: 'Mini Coach (38)', motorcoach_56: 'Motorcoach (56)', motorcoach_premium: 'Premium Motorcoach' };
const TT = (t) => { const q = t.toLowerCase(); if (!q) return ''; if (q.indexOf('airport') > -1) return 'airport transfer'; if (q.indexOf('hour') > -1) return 'hourly charter'; if (q.indexOf('point') > -1 || q === 'p2p') return 'point-to-point trip'; return t.replace(/[_-]+/g, ' '); };
const veh = VM[cf('veh').toLowerCase()] || cf('veh').replace(/[_-]+/g, ' ');
const shortAddr = (a) => a ? a.split(',')[0].trim() : '';
let when = '';
const rawWhen = cf('when');
const dt = new Date(rawWhen);
if (rawWhen && !isNaN(dt.getTime())) { const days = Math.round((Date.now() - dt.getTime()) / 86400000); if (days <= 0) when = 'today'; else if (days === 1) when = 'yesterday'; else if (days < 7) when = 'in the last week'; else if (days < 32) when = 'last month'; else when = 'back in ' + dt.toLocaleString('en-US', { month: 'long' }); }
const first = known ? s(c.firstName).split(/\s+/)[0] : '';
const co = known ? s(c.companyName) : '';
const trip = !!(known && tenOk && chaufLine && (cf('trip') || cf('doff') || cf('veh')));
const mode = (!verified || !known || !first) ? 'cold' : (co ? 'corporate' : (trip ? 'known_with_trip' : 'known'));
const vars = {
  caller_known: known ? 'true' : 'false',
  data_verified: verified ? 'true' : 'false',
  caller_first_name: first,
  caller_company: co,
  account_type: known ? (co ? 'corporate' : 'retail') : '',
  last_trip_known: trip ? 'true' : 'false',
  last_trip_type: trip ? TT(cf('trip')) : '',
  last_trip_vehicle: trip ? veh : '',
  last_trip_pickup: trip ? shortAddr(cf('pu')) : '',
  last_trip_dropoff: trip ? shortAddr(cf('doff')) : '',
  last_trip_when: trip ? when : '',
  recognition_mode: mode,
  lookup_ms: String(Date.now() - (x.t0 || Date.now()))
};
return [{ json: { vars } }];
